use std::path::PathBuf;
use clap::{Args, Subcommand, ValueEnum};

#[derive(Debug, Clone, Subcommand)]
pub enum G5kCommands {
    Deploy(DeployG5kCommand),
    Harvest(HarvestG5kCommand),
}

#[derive(Debug, Clone, Args)]
pub struct DeployG5kCommand {
    #[clap(flatten)]
    pub login: G5kLogin,

    /// Experiment batch name
    pub experiment_name: String,

    /// Experiment commands file, likely generated by `cargo run -- generate commands -q`
    pub experiment_commands: PathBuf,

    /// Grid'5000 queue to submit the job to
    #[arg(long)]
    pub queue: String,

    /// Grid'5000 job type
    #[arg(long)]
    pub job_type: Vec<String>,

    /// Queue priority level (p1..p4). Overrides --queue. Must be a level you have access to on the cluster
    #[arg(long, value_enum)]
    pub priority: Option<G5kPriority>,

    /// Grid'5000 cluster to reserve a node on
    #[arg(long)]
    pub cluster: String,

    /// Reservation walltime (ex: "3" or "3:30"). Site default if absent
    #[arg(long)]
    pub walltime: Option<String>,

    /// Do not wait for the job to terminate after submitting it
    #[arg(long)]
    pub no_wait: bool,
}

#[derive(Debug, Clone, Args)]
pub struct HarvestG5kCommand {
    #[clap(flatten)]
    pub login: G5kLogin,
}

#[derive(Debug, Clone, Args)]
pub struct G5kLogin {
    /// Grid'5000 username
    pub user: String,

    /// Grid'5000 site (ex: nancy)
    pub site: String,
}

#[derive(Debug, Clone, Copy, ValueEnum)]
pub enum G5kPriority {
    P1,
    P2,
    P3,
    P4,
}

impl DeployG5kCommand {
    pub fn effective_queue(&self) -> &str {
        match self.priority {
            Some(priority) => priority.queue_name(),
            None => self.queue.as_str()
        }
    }
}

impl G5kPriority {
    fn queue_name(self) -> &'static str {
        match self {
            Self::P1 => "p1",
            Self::P2 => "p2",
            Self::P3 => "p3",
            Self::P4 => "p4",
        }
    }
}